    until.elementLocated(By.css('[data-test="add-to-cart-sauce-labs-backpack"]')),
    5000
  );
  await addButton.click();

  // Gözlənilən nəticə
  const badge = await driver.wait(until.elementLocated(By.css('.shopping_cart_badge')), 5000);
