import { test, expect } from '@playwright/test';

const API = 'https://jsonplaceholder.typicode.com';

test('GET /users/5: şəhər Roscoeview-dur', async ({ request }) => {
  const response = await request.get(`${API}/users/5`);
  expect(response.status()).toBe(200);
  const user = await response.json();
  expect(user.address.city).toBe('Roscoeview');
});

test('POST /posts: yazı yaradılır', async ({ request }) => {
  const response = await request.post(`${API}/posts`, {
    data: { title: 'Test post', body: 'Mətn', userId: 1 },
  });
  expect(response.status()).toBe(201);
  const post = await response.json();
  expect(post.title).toBe('Test post');
  expect(typeof post.id).toBe('number');
});

