  const first = page.getByRole('checkbox').first();
  await first.check();
  await expect(first).toBeChecked();
});

test('açılan siyahı', async ({ page }) => {
  await page.goto(`${SITE}/dropdown`);
  await page.locator('#dropdown').selectOption('2');
  await expect(page.locator('#dropdown')).toHaveValue('2');
});

test('üzərinə gəlmək', async ({ page }) => {
  await page.goto(`${SITE}/hovers`);
  await page.locator('.figure').first().hover();
  await expect(page.getByText('name: user1')).toBeVisible();
});

test('təsdiq pəncərəsi', async ({ page }) => {
  await page.goto(`${SITE}/javascript_alerts`);
  page.on('dialog', dialog => dialog.dismiss());
  await page.getByRole('button', { name: 'Click for JS Confirm' }).click();
  await expect(page.locator('#result')).toHaveText('You clicked: Cancel');
});

test('yeni tab', async ({ page }) => {
  await page.goto(`${SITE}/windows`);
  const popupPromise = page.waitForEvent('popup');
  await page.getByRole('link', { name: 'Click Here' }).click();
  const popup = await popupPromise;
  await expect(popup.getByRole('heading')).toHaveText('New Window');
});
